#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define AUTH_FOUND 1
#define AUTH_NOT_FOUND 0
#define AUTH_NO_TOKENS -1
#define AUTH_ERROR -2

int check_token_in_auth_file(const char *authfile, const char *username, const char *otp_id, int verbose, FILE *debug_file) {
    FILE *file = fopen(authfile, "r");
    if (!file) {
        if (verbose && debug_file) {
            fprintf(debug_file, "Failed to open authorization file: %s\n", authfile);
        }
        return AUTH_ERROR;
    }

    char line[1024];
    int user_found = 0;
    int token_found = 0;

    while (fgets(line, sizeof(line), file)) {
        char *trimmed = line;
        while (*trimmed && isspace(*trimmed)) {
            trimmed++;
        }

        if (*trimmed == '#' || *trimmed == '\0') {
            continue;
        }

        if (!user_found) {
            if (strncmp(trimmed, username, strlen(username)) == 0) {
                user_found = 1;
                if (verbose && debug_file) {
                    fprintf(debug_file, "Username match found: %s\n", username);
                }
            }
        } else {
            if (strncmp(trimmed, otp_id, strlen(otp_id)) == 0) {
                token_found = 1;
                if (verbose && debug_file) {
                    fprintf(debug_file, "Token match found: %s\n", otp_id);
                }
                break;
            }
        }
    }

    fclose(file);

    if (!user_found) {
        return AUTH_NOT_FOUND;
    }

    if (!token_found) {
        if (verbose && debug_file) {
            fprintf(debug_file, "No token found for user: %s\n", username);
        }
        return AUTH_NO_TOKENS;
    }

    return AUTH_FOUND;
}

int check_user_token(const char *authfile, const char *username, const char *otp_id, int verbose, FILE *debug_file) {
    FILE *fp = fopen(authfile, "r");
    if (!fp) {
        if (verbose && debug_file) {
            fprintf(debug_file, "Failed to open authorization file: %s\n", authfile);
        }
        return AUTH_ERROR;
    }

    char line[1024];
    int found_user = 0;
    int found_token = 0;

    while (fgets(line, sizeof(line), fp)) {
        char *trimmed_line = line;

        // Skip leading whitespace and comments
        while (isspace((unsigned char)*trimmed_line)) {
            trimmed_line++;
        }

        if (*trimmed_line == '#') {
            continue;
        }

        // Look for the username in the line
        if (strncmp(trimmed_line, username, strlen(username)) == 0 && !found_user) {
            found_user = 1;
            if (verbose && debug_file) {
                fprintf(debug_file, "User found: %s\n", username);
            }
        }

        // Look for the OTP ID in the line
        if (found_user && !found_token) {
            if (strstr(trimmed_line, otp_id)) {
                found_token = 1;
                if (verbose && debug_file) {
                    fprintf(debug_file, "Token found for user: %s, OTP ID: %s\n", username, otp_id);
                }
            }
        }
    }

    fclose(fp);

    if (ferror(fp)) {
        if (verbose && debug_file) {
            fprintf(debug_file, "Error reading authorization file: %s\n", authfile);
        }
        return AUTH_ERROR;
    }

    if (!found_user) {
        return AUTH_NOT_FOUND;
    }

    if (!found_token) {
        return AUTH_NO_TOKENS;
    }

    return AUTH_FOUND;
}

