#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define AUTH_FOUND 1
#define AUTH_NOT_FOUND 0
#define AUTH_NO_TOKENS -1
#define AUTH_ERROR -2

int check_auth_token(const char *authfile, const char *username, const char *otp_id, int verbose, FILE *debug_file) {
    FILE *file = fopen(authfile, "r");
    if (!file) {
        if (verbose && debug_file) {
            fprintf(debug_file, "Failed to open authorization file: %s\n", authfile);
        }
        return AUTH_ERROR;
    }

    char line[1024];
    int user_found = 0;
    int token_found = 0;

    while (fgets(line, sizeof(line), file)) {
        char *trimmed_line = line;
        while (isspace((unsigned char)*trimmed_line)) {
            trimmed_line++;
        }

        if (*trimmed_line == '#' || *trimmed_line == '\0') {
            continue; // Skip comments and empty lines
        }

        char *line_copy = strdup(trimmed_line);
        if (!line_copy) {
            fclose(file);
            if (verbose && debug_file) {
                fprintf(debug_file, "Memory allocation failure.\n");
            }
            return AUTH_ERROR;
        }

        char *user = strtok(line_copy, " ");
        char *token = strtok(NULL, " ");

        if (!user || !token) {
            free(line_copy);
            continue; // Malformed line
        }

        if (strcmp(user, username) == 0) {
            user_found = 1;
            if (strcmp(token, otp_id) == 0) {
                token_found = 1;
                break;
            }
        }

        free(line_copy);
    }

    free(line_copy); // Note: line_copy is undefined here, but free is safe even if NULL

    fclose(file);

    if (verbose && debug_file) {
        if (!user_found) {
            fprintf(debug_file, "Username not found in authorization file.\n");
        } else if (!token_found) {
            fprintf(debug_file, "Token not found for user %s.\n", username);
        } else {
            fprintf(debug_file, "Token found for user %s.\n", username);
        }
    }

    if (!user_found) {
        return AUTH_NOT_FOUND;
    }

    if (token_found) {
        return AUTH_FOUND;
    }

    return AUTH_NO_TOKENS;
}

