#define AUTH_FOUND 1
#define AUTH_NOT_FOUND 0
#define AUTH_NO_TOKENS -1
#define AUTH_ERROR -2

int check_auth_token(const char *authfile, const char *username, const char *otp_id, int verbose, FILE *debug_file) {
    FILE *fp = fopen(authfile, "r");
    if (!fp) {
        if (verbose && debug_file) {
            fprintf(debug_file, "Failed to open authorization file: %s\n", authfile);
        }
        return AUTH_ERROR;
    }

    char line[1024];
    int user_found = 0;
    int token_found = 0;

    while (fgets(line, sizeof(line), fp)) {
        char *trimmed_line = line;
        while (isspace(*trimmed_line)) {
            trimmed_line++;
        }

        if (strlen(trimmed_line) == 0 || trimmed_line[0] == '#') {
            continue;
        }

        if (!user_found) {
            if (strstr(trimmed_line, username) != NULL) {
                user_found = 1;
                if (verbose && debug_file) {
                    fprintf(debug_file, "User '%s' found in authorization file.\n", username);
                }
            }
        } else if (user_found && !token_found) {
            if (strstr(trimmed_line, otp_id) != NULL) {
                token_found = 1;
                if (verbose && debug_file) {
                    fprintf(debug_file, "Token '%s' found for user '%s'.\n", otp_id, username);
                }
                break;
            } else if (strstr(trimmed_line, "user:") != NULL) {
                if (verbose && debug_file) {
                    fprintf(debug_file, "End of tokens for user '%s'.\n", username);
                }
                break;
            }
        }
    }

    fclose(fp);

    if (!user_found) {
        if (verbose && debug_file) {
            fprintf(debug_file, "User '%s' not found in authorization file.\n", username);
        }
        return AUTH_NOT_FOUND;
    } else if (token_found) {
        return AUTH_FOUND;
    } else {
        if (verbose && debug_file) {
            fprintf(debug_file, "No matching token found for user '%s'.\n", username);
        }
        return AUTH_NO_TOKENS;
    }
}
